param([string]$SourcePath='assets/exercises/anatomy/templates/male_neutral_anatomy_master_v3.png',[string]$OutputPath='assets/exercises/anatomy/templates/male_neutral_anatomy_artwork_reference_v3.png',[string]$ExpectedSourceSha256='A6AB0866E7849F3B0CF583187B94EFF3CDA8981B54DDC11F2001D1AF5B47A228')
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$sourceFull=Join-Path $root $SourcePath;$outputFull=Join-Path $root $OutputPath
if(-not(Test-Path $sourceFull)-or(Get-FileHash -Algorithm SHA256 $sourceFull).Hash-ne$ExpectedSourceSha256){throw 'Locked Male V3 master missing or hash mismatch.'};if(Test-Path $outputFull){throw 'Male artwork reference destination already exists.'}
Add-Type -AssemblyName System.Drawing;$source=[Drawing.Bitmap]::new($sourceFull)
try{if($source.Width-ne512-or$source.Height-ne512){throw 'Unexpected Male V3 dimensions.'};$output=[Drawing.Bitmap]::new(1024,1024);try{$g=[Drawing.Graphics]::FromImage($output);try{$g.Clear([Drawing.Color]::White);$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$g.DrawImage($source,[Drawing.Rectangle]::new(32,12,960,1000),[Drawing.Rectangle]::new(22,78,320,334),[Drawing.GraphicsUnit]::Pixel)}finally{$g.Dispose()};for($y=0;$y-lt1024;$y++){for($x=0;$x-lt1024;$x++){$p=$output.GetPixel($x,$y);if($p.R-gt185-and$p.G-gt$p.R-and$p.B-gt($p.R+8)){$output.SetPixel($x,$y,[Drawing.Color]::White)}}};[IO.Directory]::CreateDirectory((Split-Path $outputFull))|Out-Null;$stream=[IO.File]::Open($outputFull,[IO.FileMode]::CreateNew);try{$output.Save($stream,[Drawing.Imaging.ImageFormat]::Png)}finally{$stream.Dispose()}}finally{$output.Dispose()}}finally{$source.Dispose()}
[ordered]@{path=$OutputPath;sha256=(Get-FileHash -Algorithm SHA256 $outputFull).Hash;width=1024;height=1024;source_sha256=$ExpectedSourceSha256}|ConvertTo-Json -Compress
